import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"常用网站","description":"按官方文档、模型平台、工具框架与学习资源分类整理常用 AI 网站，并说明验证时效和许可证的方法。","frontmatter":{"description":"按官方文档、模型平台、工具框架与学习资源分类整理常用 AI 网站，并说明验证时效和许可证的方法。"},"headers":[],"relativePath":"resources/websites.md","filePath":"resources/websites.md","lastUpdated":1788308924000}'),i={name:"resources/websites.md"};function o(n,a,h,s,c,g){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="常用网站" tabindex="-1">常用网站 <a class="header-anchor" href="#常用网站" aria-label="Permalink to &quot;常用网站&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 这份清单按用途分组：先用官方课程补概念，再用平台查模型与论文，最后按工具找官方文档。下载或引用任何资源前，先读模型卡、许可证和官方当前说明——外部资源随时可能更新，遇到冲突以官方为准。</p></blockquote><p>本页链接与描述核对于 2026 年 9 月；网站与平台迭代较快，使用前请以官方页面为准。</p><h2 id="ai-与-llm-官方学习" tabindex="-1">AI 与 LLM 官方学习 <a class="header-anchor" href="#ai-与-llm-官方学习" aria-label="Permalink to &quot;AI 与 LLM 官方学习&quot;">​</a></h2><p>这组解决“概念从哪学”：官方出品的系统课程，负责在动手之前把基础概念补齐。</p><h3 id="google-machine-learning" tabindex="-1">Google Machine Learning <a class="header-anchor" href="#google-machine-learning" aria-label="Permalink to &quot;Google Machine Learning&quot;">​</a></h3><p>地址：<a href="https://developers.google.com/machine-learning" target="_blank" rel="noreferrer">https://developers.google.com/machine-learning</a></p><p>用途：</p><ul><li>学习机器学习基础、数据、模型和大语言模型概念。</li><li>通过短课程建立从 Token 到 Transformer 的基础认识。</li><li>适合在阅读框架文档前补齐通用概念。</li></ul><h3 id="hugging-face-llm-course" tabindex="-1">Hugging Face LLM Course <a class="header-anchor" href="#hugging-face-llm-course" aria-label="Permalink to &quot;Hugging Face LLM Course&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">https://huggingface.co/learn/llm-course/chapter1/1</a></p><p>用途：</p><ul><li>系统学习 Transformer、Tokenizer、推理和微调。</li><li>配合 Hugging Face 模型与数据生态进行实践。</li><li>课程以英文和代码为主，适合掌握本站基础概念后继续学习。</li></ul><h3 id="hugging-face-agents-course" tabindex="-1">Hugging Face Agents Course <a class="header-anchor" href="#hugging-face-agents-course" aria-label="Permalink to &quot;Hugging Face Agents Course&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/learn/agents-course/en/unit0/introduction" target="_blank" rel="noreferrer">https://huggingface.co/learn/agents-course/en/unit0/introduction</a></p><p>用途：</p><ul><li>学习 Agent、Tool Use、Function Calling 和 Agentic RAG。</li><li>了解常见框架和评估方式。</li><li>内容更新较快，使用时注意课程单元和依赖版本。</li></ul><h2 id="模型与数据平台" tabindex="-1">模型与数据平台 <a class="header-anchor" href="#模型与数据平台" aria-label="Permalink to &quot;模型与数据平台&quot;">​</a></h2><p>这组解决“模型从哪来、怎么读说明”：下载前在这里核对模型卡、许可证和推荐参数。</p><h3 id="hugging-face" tabindex="-1">Hugging Face <a class="header-anchor" href="#hugging-face" aria-label="Permalink to &quot;Hugging Face&quot;">​</a></h3><p>地址：<a href="https://huggingface.co" target="_blank" rel="noreferrer">https://huggingface.co</a></p><p>用途：</p><ul><li>查找模型、数据集、演示和官方文档。</li><li>查看模型卡、许可证、文件结构和推荐用法。</li><li>比较不同任务、框架和模型版本。</li></ul><p>下载或调用模型前先核对发布者、许可证、所需文件、量化格式和用途限制。</p><h3 id="civitai" tabindex="-1">Civitai <a class="header-anchor" href="#civitai" aria-label="Permalink to &quot;Civitai&quot;">​</a></h3><p>地址：<a href="https://civitai.com" target="_blank" rel="noreferrer">https://civitai.com</a></p><p>用途：</p><ul><li>查找 AI 绘画 checkpoint、LoRA、VAE、工作流和示例图。</li><li>查看示例 Prompt、推荐参数和社区反馈。</li></ul><p>这是社区平台，模型质量、来源、许可证和内容分级差异很大，公开使用前要逐项核对。</p><h2 id="论文与研究进展" tabindex="-1">论文与研究进展 <a class="header-anchor" href="#论文与研究进展" aria-label="Permalink to &quot;论文与研究进展&quot;">​</a></h2><p>这组解决“新知识从哪追踪”：查找原始论文，判断一个说法有没有出处。</p><h3 id="arxiv" tabindex="-1">arXiv <a class="header-anchor" href="#arxiv" aria-label="Permalink to &quot;arXiv&quot;">​</a></h3><p>地址：<a href="https://arxiv.org" target="_blank" rel="noreferrer">https://arxiv.org</a></p><p>用途：查找 AI、机器学习、自然语言处理和计算机视觉论文预印本。预印本不等于已经同行评审，结论需要结合正式论文、代码和后续研究判断。</p><h3 id="hugging-face-papers" tabindex="-1">Hugging Face Papers <a class="header-anchor" href="#hugging-face-papers" aria-label="Permalink to &quot;Hugging Face Papers&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/papers" target="_blank" rel="noreferrer">https://huggingface.co/papers</a></p><p>用途：按日浏览 AI 论文与社区讨论，跟踪研究方向。原来的 Papers with Code 站点已停止服务并跳转至此；论文是否可靠，仍需结合正式发表版本、代码与后续研究判断。</p><h2 id="rag、agent-与本地模型" tabindex="-1">RAG、Agent 与本地模型 <a class="header-anchor" href="#rag、agent-与本地模型" aria-label="Permalink to &quot;RAG、Agent 与本地模型&quot;">​</a></h2><p>这组解决“应用框架与本地部署的文档在哪”：把本站原理页对应到具体框架的官方文档。</p><h3 id="langchain-文档" tabindex="-1">LangChain 文档 <a class="header-anchor" href="#langchain-文档" aria-label="Permalink to &quot;LangChain 文档&quot;">​</a></h3><p>地址：<a href="https://docs.langchain.com" target="_blank" rel="noreferrer">https://docs.langchain.com</a></p><p>用途：了解模型调用、工具、检索和 Agent 应用结构。框架 API 变化较快，示例代码必须对应当前文档版本。</p><h3 id="llamaindex-文档" tabindex="-1">LlamaIndex 文档 <a class="header-anchor" href="#llamaindex-文档" aria-label="Permalink to &quot;LlamaIndex 文档&quot;">​</a></h3><p>地址：<a href="https://docs.llamaindex.ai" target="_blank" rel="noreferrer">https://docs.llamaindex.ai</a></p><p>用途：学习文档加载、索引、检索、RAG 和 Agent 数据流程。</p><h3 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h3><p>地址：<a href="https://ollama.com" target="_blank" rel="noreferrer">https://ollama.com</a></p><p>用途：查看本地模型运行工具、支持模型和使用文档。下载模型前仍需阅读原始模型许可证和硬件要求。</p><h2 id="ai-绘画工具与项目" tabindex="-1">AI 绘画工具与项目 <a class="header-anchor" href="#ai-绘画工具与项目" aria-label="Permalink to &quot;AI 绘画工具与项目&quot;">​</a></h2><p>这组解决“绘画工具与模型发布在哪看”：工具、底模与官方公告的第一手来源。</p><h3 id="comfyui" tabindex="-1">ComfyUI <a class="header-anchor" href="#comfyui" aria-label="Permalink to &quot;ComfyUI&quot;">​</a></h3><p>地址：<a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">https://github.com/Comfy-Org/ComfyUI</a></p><p>用途：</p><ul><li>获取节点式 AI 绘画工具和发布说明。</li><li>学习工作流、节点数据流和模型支持情况。</li><li>排查自定义节点和核心版本兼容问题。</li></ul><h3 id="stability-ai" tabindex="-1">Stability AI <a class="header-anchor" href="#stability-ai" aria-label="Permalink to &quot;Stability AI&quot;">​</a></h3><p>地址：<a href="https://stability.ai" target="_blank" rel="noreferrer">https://stability.ai</a></p><p>用途：了解 Stable Diffusion 相关模型与项目公告。</p><h3 id="black-forest-labs" tabindex="-1">Black Forest Labs <a class="header-anchor" href="#black-forest-labs" aria-label="Permalink to &quot;Black Forest Labs&quot;">​</a></h3><p>地址：<a href="https://bfl.ai" target="_blank" rel="noreferrer">https://bfl.ai</a></p><p>用途：了解 FLUX 系列模型与相关发布。</p><h2 id="文档建设" tabindex="-1">文档建设 <a class="header-anchor" href="#文档建设" aria-label="Permalink to &quot;文档建设&quot;">​</a></h2><p>这组解决“本站怎么搭”：想维护自己的知识库，从这里开始。</p><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h3><p>地址：<a href="https://vitepress.dev" target="_blank" rel="noreferrer">https://vitepress.dev</a></p><p>用途：搭建静态文档站、个人知识库和项目教程。</p><h2 id="精选教程入口" tabindex="-1">精选教程入口 <a class="header-anchor" href="#精选教程入口" aria-label="Permalink to &quot;精选教程入口&quot;">​</a></h2><p>这组解决“先看哪个教程”：完整清单见 <a href="/resources/tutorials">精选教程</a>，这里只留三个最推荐的入口：</p><ul><li><a href="https://developers.google.com/machine-learning/crash-course/llm" target="_blank" rel="noreferrer">Google LLM 入门课程</a>：建立大模型基础概念。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">Hugging Face LLM Course</a>：继续学习 Transformer 与模型实践。</li><li><a href="https://docs.comfy.org/zh" target="_blank" rel="noreferrer">ComfyUI 官方中文文档</a>：进入 AI 绘画工作流。</li></ul><h2 id="使用外部资源的原则" tabindex="-1">使用外部资源的原则 <a class="header-anchor" href="#使用外部资源的原则" aria-label="Permalink to &quot;使用外部资源的原则&quot;">​</a></h2><ul><li>优先看官方文档、模型卡和官方示例，并检查更新时间。</li><li>下载模型、数据或代码前确认发布者、许可证和用途限制。</li><li>不把未知来源模型、数据、角色或素材直接用于公开或商业项目。</li><li>记录来源、版本、访问日期和关键配置，保证以后可以复查。</li><li>社区教程用于补充操作经验，涉及参数、下载和兼容性时回到官方资料核对。</li></ul><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>下一篇：<a href="/resources/tutorials">精选教程</a>：从“知道网站”到“跟着练”，按类型挑选入门教程。</li></ul>',72)])])}const d=e(i,[["render",o]]);export{u as __pageData,d as default};
